Inductive List = cons {Int, List} | nil Unit;

Inductive CList = cnil Unit | single Int | concat {CList, CList};

cat = fix (\f: List -> List -> List. \xs: List. \ys: List.
  match xs with
    nil _ -> ys
  | cons {h, t} -> cons {h, f t ys}
  end
);

flatten = fix (\f: CList -> Compress List. \c: CList.
  match c with
    cnil _ -> let tmp = (nil unit) in align (label tmp)
  | single x -> let tmp = (cons {x, nil unit}) in align (label tmp)
  | concat {l, r} ->
      let left = (f l) in
      let right = (f r) in
      align (label (cat (unlabel left) (unlabel right)))
  end
);

sum = fix (\f: List -> Int. \xs: List.
  match xs with
    nil _ -> 0
  | cons {h, t} -> + h (f t)
  end
);

main = \c: CList.
  let tmp = (flatten c) in
  align (sum (unlabel tmp));
